1	/**
2	 * deployed-config.test.ts — this repository's OWN config.yaml, validated.
3	 *
4	 * ## The failure this exists for
5	 *
6	 * `validate_deliverable.ts` checks the `.github/atomaton/` a pull request would
7	 * merge, and it ran on every pull request. What nothing checked is whether
8	 * `src/content/config.yaml` — the template — and `.github/atomaton/config.yaml` —
9	 * this repository's copy of its own config — say the same thing about a key that
10	 * is REQUIRED.
11	 *
12	 * The `agents` section was added to the template with `on_config_finding` required,
13	 * and this repository's own copy was never given one. The consequence was not a
14	 * warning. `configProblems` reported it for the tree every pull request would merge,
15	 * `decideValidationOutcome` turned that into `deliverable-invalid`, and CI was never
16	 * dispatched — so EVERY pull request in this repository failed validation before its
17	 * checks ran, for a setting none of them touched. Recovering the first one meant a
18	 * second agent run whose whole content was the one-line fix, and the pull request
19	 * that found it could not be reviewed until that landed.
20	 *
21	 * ## Why this file and not one of the three that read a config
22	 *
23	 * `config-contract.test.ts` validates the SHIPPED config against `configProblems`,
24	 * `merge-gate-targets.test.ts` compares the two copies' merge gates, and the
25	 * machinery's own update three-way merges the deployed copy — so a change to the
26	 * shipped copy alone is already visible. The hole is the case nobody reads: the
27	 * deployed copy the agents here actually run under, against the validator, with the
28	 * names that sit beside it. `src/content/config.yaml` is not that — it is the
29	 * template, it is not what the agents here run under, and it is the one that had
30	 * the key.
31	 */
32	import { describe, expect, test } from "bun:test";
33	import { readdirSync, readFileSync } from "node:fs";
34	import { join } from "node:path";
35	import { configProblems } from "../../src/domain/delivery/deliverable-integrity.ts";
36	
37	/** This repository's own config, the one the live agents run under. */
38	const CONFIGS = [".github/atomaton/config.yaml"];
39	
40	function agentNames(dir: string): string[] {
41	  return readdirSync(dir)
42	    .filter((file) => file.endsWith(".md"))
43	    .map((file) => file.slice(0, -".md".length))
44	    .sort();
45	}
46	
47	function problemsFor(configPath: string): string[] {
48	  return configProblems({
49	    config: Bun.YAML.parse(readFileSync(configPath, "utf8")),
50	    // The definitions and workflows that sit beside THIS config, which is what the
51	    // validator checks a name against. Reading the shipped ones would answer a
52	    // different question: whether the template is self-consistent.
53	    agentNames: agentNames(".github/atomaton/agent-definitions"),
54	    workflowFiles: readdirSync(".github/workflows"),
55	  });
56	}
57	
58	describe.each(CONFIGS)("%s", (configPath) => {
59	  /**
60	   * The keys `configProblems` requires rather than defaults, checked here so the
61	   * failure names the config a person has to edit. `agents.on_config_finding` is
62	   * the one that was missing; the assertion is deliberately over the whole list
63	   * rather than that key alone, so the next required key is covered on the day it
64	   * is added to `REQUIRED_AGENT_KEYS`.
65	   */
66	  test("is internally consistent, so CI runs on the pull requests that follow", () => {
67	    expect(
68	      problemsFor(configPath),
69	      `${configPath} is what this repository's agents actually run under, and what every pull ` +
70	        `request's validation reads. A problem here blocks CI for every pull request, not only ` +
71	        `the one that touched it`,
72	    ).toEqual([]);
73	  });
74	});
75	
76	describe("the shipped template and this repository's own config", () => {
77	  /**
78	   * The direction the drift actually went: the template gained a required key and
79	   * this repository's copy did not follow. Not a byte comparison — the two are
80	   * this repository's own adoption and the shipped template, and may differ by
81	   * design. This checks the keys that make the deliverable valid.
82	   */
83	  test("both set every agent a workflow starts with no thread to read", () => {
84	    const shipped = Bun.YAML.parse(readFileSync("src/content/config.yaml", "utf8")) as {
85	      agents?: Record<string, unknown>;
86	    };
87	    const own = Bun.YAML.parse(readFileSync(CONFIGS[0]!, "utf8")) as { agents?: Record<string, unknown> };
88	    for (const key of Object.keys(shipped.agents ?? {})) {
89	      expect(own.agents?.[key], `${key} is in src/content/config.yaml and missing here`).toBe(
90	        shipped.agents![key],
91	      );
92	    }
93	  });
94	
95	  // A walk that finds nothing compares equal to one that passes -- the shape both
96	  // this file and `config-contract.test.ts` were written after.
97	  test("the inputs this reads are really there", () => {
98	    expect(agentNames(".github/atomaton/agent-definitions").length).toBeGreaterThan(0);
99	    expect(readdirSync(join(".github", "workflows")).length).toBeGreaterThan(0);
100	  });
101	});

