5	const EXAMPLES_DIR = "examples/workflows";
6	
7	/**
8	 * `examples/` is for the adopter to copy, and must never become deliverable.
9	 *
10	 * The whole point of the recurring-work example is that Atomaton does not install
11	 * it: `on:` takes no expression, so a schedule cannot come from configuration,
12	 * and an agent cannot write `.github/workflows/**` at all. If one of these files
13	 * ever reached `dist/.github/workflows/`, every adopter would start running a
14	 * schedule nobody asked for -- and the one whose cron fires an agent run would
15	 * be paying for it.
16	 *
17	 * Nothing in `build-dist.ts` or `wac.config.ts` looks at `examples/` today. This
18	 * is here so that stays true, since the failure is silent and arrives by upgrade.
19	 */
20	describe("examples are examples", () => {
21	  const examples = readdirSync(EXAMPLES_DIR);
22	
23	  test("there is something to check", () => {
24	    expect(examples.length).toBeGreaterThan(0);
25	  });
26	
27	  test("none of them is generated into the deliverable", () => {
28	    const distWorkflows = "dist/.github/workflows";
29	    const shipped = existsSync(distWorkflows) ? readdirSync(distWorkflows) : [];
30	    for (const example of examples) {
31	      expect(shipped, `${example} must not be deployed`).not.toContain(example);
32	    }
33	  });
34	
35	  // Plain YAML, not `.wac.ts`, and the extension is load-bearing rather than a
36	  // style choice: it is what says these are not workflow sources. The generator
37	  // reads `src/workflows/` only (see `workflow-sources.test.ts`), so a `.wac.ts`
38	  // here would not be generated today -- but that bound is one directory, and
39	  // moving `examples/` under it would then ship a schedule to every adopter.
40	  test("none of them is a workflow source file", () => {
41	    for (const example of examples) {
42	      expect(example.endsWith(".wac.ts"), example).toBe(false);
43	      expect(example.endsWith(".yml") || example.endsWith(".yaml"), example).toBe(true);
44	    }
45	  });
46	
47	  // The step that hands the issue to an agent is the one thing a reader is most
48	  // likely to drop as boilerplate, and dropping it is silent: the issue appears
49	  // and nothing ever picks it up, because GitHub raises no `issues: opened`
50	  // event for an issue its own token created.
51	  test("the scheduled example dispatches the runner explicitly", () => {
52	    const yaml = readFileSync(join(EXAMPLES_DIR, "scheduled-issue.yml"), "utf8");
53	    expect(yaml).toContain("gh workflow run atomaton-runner.yml");
54	    expect(yaml).toContain("issues: write");
55	    // And it does not create a second issue while the first is still open.
56	    expect(yaml).toContain("--state open");
57	  });
58	
59	  // No heredocs in an example meant to be copied.
60	  //
61	  // A heredoc's terminator has to match its line exactly. This file is checked
62	  // out with CRLF on Windows, and someone copying it into their own repository
63	  // carries that through -- at which point the runner's bash looks for `BODY`,
64	  // reads `BODY`, never ends the document, and fails somewhere that looks
