134	          `Listed: ${[...table.keys()].sort().join(", ")}`,
135	      ).toBe(true);
136	    }
137	  });
138	
139	  test("the setup guide names the credential the shipped configuration needs", () => {
140	    const table = credentialByProvider();
141	    const preflight = preflightSection();
142	    for (const file of agentFiles) {
143	      const credential = table.get(providerOf(file)!);
144	      expect(
145	        preflight.includes(credential!),
146	        `${file} runs on ${providerOf(file)}, which authenticates with ${credential} — ` +
147	          `and the preflight checklist does not name it. A first run cannot start.`,
148	      ).toBe(true);
149	    }
150	  });
151	
152	  /**
153	   * The inverse, and the direction the drift actually went: the checklist named
154	   * `OPENAI_API_KEY` long after nothing shipped used it. A credential named as
155	   * required, that nothing reads, sends an adopter to create a secret that does
156	   * not help and then to debug a failure the checklist caused.
